+++ b/drivers/mmc/host/renesas_sdhi_core.c
@@ -1400,6 +1400,15 @@ int renesas_sdhi_suspend(struct device *dev)
 	};
 	int ret;
 
+	if (priv->rdev) {
+		PM_RUNTIME_ACQUIRE_IF_ENABLED(dev, pm);
